import { WastageAlert, SimulatedTelemetry } from '../types/telemetry.types';
import { RoomMetadata } from '../types/room.types';

export interface AIAnomalyInsight {
  confidenceScore: number;
  anomalyType: 'GHOST_LOAD_AFTER_CLASS' | 'LUNCH_BREAK_AIR_CONDITIONING' | 'UNAUTHORIZED_LAB_IDLE' | 'ABSENT_FACULTY_LEAK';
  summary: string;
  rootCauseAnalysis: string;
  recommendedAction: string;
  projectedAnnualSavingRoomInr: number;
}

/**
 * Simulates real-time reasoning generated by Google Gemini 2.0 Flash
 * Cross-correlating timetable, sensor presence, and electrical signature.
 */
export function generateAIAnomalyInsight(
  alert: WastageAlert,
  telemetry: SimulatedTelemetry,
  room: RoomMetadata
): AIAnomalyInsight {
  if (alert.reason.includes('Break')) {
    return {
      confidenceScore: 0.98,
      anomalyType: 'LUNCH_BREAK_AIR_CONDITIONING',
      summary: `High probability of unattended climate control waste during institutional lunch interval.`,
      rootCauseAnalysis: `PZEM-004T reports steady ${telemetry.simulatedPowerWatts}W active load with 0.95 power factor, matching dual 1.5-ton AC compressors. Timetable indicates campus-wide break; PIR sensor reports zero motion across last 15 minutes.`,
      recommendedAction: `Trigger automated Eco-Off contactor pulse. Pre-cool restart scheduled for 2:05 PM (5 mins prior to next lecture).`,
      projectedAnnualSavingRoomInr: 9450,
    };
  }

  if (alert.reason.includes('CANCELLED')) {
    return {
      confidenceScore: 0.99,
      anomalyType: 'ABSENT_FACULTY_LEAK',
      summary: `Confirmed class cancellation with unmitigated circuit power dissipation.`,
      rootCauseAnalysis: `Faculty member cancelled scheduled theory lecture via portal. However, physical wall switches and room contactors remained energized, drawing ${alert.excessWatts}W into an unoccupied room.`,
      recommendedAction: `Engage 1-Click Automated Remediate. Release room metadata to student study-room pool.`,
      projectedAnnualSavingRoomInr: 6800,
    };
  }

  if (room.roomType === 'LABORATORY') {
    return {
      confidenceScore: 0.95,
      anomalyType: 'UNAUTHORIZED_LAB_IDLE',
      summary: `Substantial laboratory workstation standby leak during unscheduled period.`,
      rootCauseAnalysis: `Continuous active draw of ${telemetry.simulatedPowerWatts}W consistent with ~30 computer workstations left booted in idle state after practical session.`,
      recommendedAction: `Dispatch network Wake-on-LAN/Sleep script to client terminals and switch off secondary air conditioning.`,
      projectedAnnualSavingRoomInr: 18200,
    };
  }

  return {
    confidenceScore: 0.92,
    anomalyType: 'GHOST_LOAD_AFTER_CLASS',
    summary: `Ghost lighting and ventilation load in vacant classroom.`,
    rootCauseAnalysis: `Room occupancy profile has transitioned from SCHEDULED to VACANT, but lighting and fan circuits remain active with zero occupant detection.`,
    recommendedAction: `Deploy contactor trip after 5-minute safety veto grace period.`,
    projectedAnnualSavingRoomInr: 5200,
  };
}
